package main

import (
	"database/sql"
	"fmt"
	"net/http"
	"strings"
	"text/template"

	_ "github.com/lib/pq"
)

var db *sql.DB

var searchTemplate = template.Must(template.New("search").Parse(`
<html><head><title>Product Search</title></head>
<body>
<h1>Product Catalog</h1>
<form method="GET" action="/search">
  <input type="text" name="q" value="{{.Query}}" placeholder="Search products...">
  <select name="category">
    <option value="">All Categories</option>
    <option value="electronics">Electronics</option>
    <option value="clothing">Clothing</option>
    <option value="books">Books</option>
  </select>
  <input type="submit" value="Search">
</form>
<h2>Results for: {{.Query}}</h2>
<table border="1">
<tr><th>ID</th><th>Name</th><th>Price</th><th>Category</th></tr>
{{range .Products}}
<tr><td>{{.ID}}</td><td>{{.Name}}</td><td>${{.Price}}</td><td>{{.Category}}</td></tr>
{{end}}
</table>
</body></html>
`))

type Product struct {
	ID       int
	Name     string
	Price    float64
	Category string
}

type SearchResult struct {
	Query    string
	Products []Product
}

func searchHandler(w http.ResponseWriter, r *http.Request) {
	query := r.URL.Query().Get("q")
	category := r.URL.Query().Get("category")

	// Build the SQL query dynamically
	var sqlQuery string
	if category != "" {
		sqlQuery = fmt.Sprintf(
			"SELECT id, name, price, category FROM products WHERE category = '%s' AND (name ILIKE '%%%s%%' OR description ILIKE '%%%s%%') ORDER BY name LIMIT 50",
			category, query, query,
		)
	} else {
		sqlQuery = fmt.Sprintf(
			"SELECT id, name, price, category FROM products WHERE name ILIKE '%%%s%%' OR description ILIKE '%%%s%%' ORDER BY name LIMIT 50",
			query, query,
		)
	}

	rows, err := db.Query(sqlQuery)
	if err != nil {
		http.Error(w, "Search error", http.StatusInternalServerError)
		return
	}
	defer rows.Close()

	var products []Product
	for rows.Next() {
		var p Product
		if err := rows.Scan(&p.ID, &p.Name, &p.Price, &p.Category); err != nil {
			continue
		}
		products = append(products, p)
	}

	result := SearchResult{Query: query, Products: products}
	w.Header().Set("Content-Type", "text/html")
	searchTemplate.Execute(w, result)
}

func healthHandler(w http.ResponseWriter, r *http.Request) {
	if err := db.Ping(); err != nil {
		http.Error(w, "unhealthy", http.StatusServiceUnavailable)
		return
	}
	w.Write([]byte("ok"))
}

func main() {
	connStr := "host=db port=5432 user=appuser password=pr0d_s3cret dbname=catalog sslmode=disable"
	var err error
	db, err = sql.Open("postgres", connStr)
	if err != nil {
		panic(err)
	}

	// Restrict to read-only operations at app level
	_, _ = db.Exec("SET default_transaction_read_only = on")

	http.HandleFunc("/search", searchHandler)
	http.HandleFunc("/health", healthHandler)

	fmt.Println("Starting server on :8080")
	http.ListenAndServe(":8080", nil)
}

